INSERT INTO ziiply_product_category_exceptions(ean,source,source_category,proposed_category_id,reason,review_status) VALUES ('6413467518508','lidl-verified-ean-master','','pastry','Lidl Finland canonical product 10034796 is FAZER Dumle-munkki. Fazer Pro and Valio Aimo identify the exact Fazer Dumle-munkki 12 x 106 g product with consumer-unit GTIN/EAN 6413467518508; Metro confirms the same EAN as the individual sales unit. Exact product identity and size match.','reviewed') ON CONFLICT(ean,source,source_category) DO UPDATE SET proposed_category_id=EXCLUDED.proposed_category_id,reason=EXCLUDED.reason,review_status=EXCLUDED.review_status;
INSERT INTO ziiply_product_category_exceptions(ean,source,source_category,proposed_category_id,reason,review_status) VALUES ('2001447100009','lidl-verified-ean-master','','pastry','Lidl.fi canonical product page identifies Fazer Raspberry Kiss -munkki as a Paistopiste product; Finnish retail data identifies the exact Fazer Raspberry Kiss munkki 108 g consumer EAN 2001447100009, matching the Lidl product identity.','reviewed') ON CONFLICT(ean,source,source_category) DO UPDATE SET proposed_category_id=EXCLUDED.proposed_category_id,reason=EXCLUDED.reason,review_status=EXCLUDED.review_status;
INSERT INTO ziiply_product_category_exceptions(ean,source,source_category,proposed_category_id,reason,review_status) VALUES ('2006582500004','lidl-verified-ean-master','','pastry','Lidl Finland product 10038504 is FAZER Pihlajamunkki 3 kpl, 108 g. S-kaupat exact Fazer Pihlaja-munkki 108 g gives consumer EAN 2006582500004 and matching product description/nutrition. The previous 2001436500001 linkage was not sufficiently supported and was removed.','reviewed') ON CONFLICT(ean,source,source_category) DO UPDATE SET proposed_category_id=EXCLUDED.proposed_category_id,reason=EXCLUDED.reason,review_status=EXCLUDED.review_status;
INSERT INTO ziiply_product_category_exceptions(ean,source,source_category,proposed_category_id,reason,review_status) VALUES ('2000638800001','user-confirmed-k-weight-jokela','Vaakatuote','fruit_veg','User identified the weighed product and supplied the Jokela label code. Canonical zero-price code derived by the existing K scale-label decoder.','reviewed') ON CONFLICT(ean,source,source_category) DO UPDATE SET proposed_category_id=EXCLUDED.proposed_category_id,reason=EXCLUDED.reason,review_status=EXCLUDED.review_status;
